"""Data processing runner for mini_harness."""

from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Iterable


class HarnessError(Exception):
    """Raised when the harness cannot process input data."""


def _has_non_empty_id(record: dict) -> bool:
    for key, value in record.items():
        if str(key).strip().lower() == "id":
            return value is not None and str(value).strip() != ""
    return False


def _iter_csv(path: Path) -> Iterable[dict]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        reader = csv.DictReader(line for line in handle if line.strip())
        if not reader.fieldnames:
            return
        for row in reader:
            yield row


def _iter_jsonl(path: Path) -> Iterable[dict]:
    with path.open("r", encoding="utf-8-sig") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError as exc:
                raise HarnessError(f"Invalid JSONL in {path} at line {line_number}: {exc.msg}") from exc
            if not isinstance(item, dict):
                raise HarnessError(f"JSONL record in {path} at line {line_number} is not an object")
            yield item


def _iter_records(path: Path) -> Iterable[dict]:
    suffix = path.suffix.lower()
    if suffix == ".csv":
        yield from _iter_csv(path)
    elif suffix == ".jsonl":
        yield from _iter_jsonl(path)
    else:
        raise HarnessError(f"Unsupported input file type: {path}")


def run_dag(input_files: list[str] | tuple[str, ...], output: str | None = None) -> dict:
    """Process CSV/JSONL files and optionally write a JSON report."""
    if not input_files:
        raise HarnessError("At least one input file is required")

    processed_count = 0
    rejected_count = 0

    try:
        for file_name in input_files:
            path = Path(file_name)
            if not path.exists():
                raise HarnessError(f"Input file not found: {file_name}")
            for record in _iter_records(path):
                if _has_non_empty_id(record):
                    processed_count += 1
                else:
                    rejected_count += 1
    except OSError as exc:
        raise HarnessError(str(exc)) from exc

    report = {
        "processed_count": processed_count,
        "rejected_count": rejected_count,
        "retry_count": 0,
        "source_files": list(input_files),
    }

    if output is not None:
        output_path = Path(output)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    return report

"""Command-line entry point for mini_harness."""

from __future__ import annotations

import argparse
import sys

from .runner import HarnessError, run_dag


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="mini_harness")
    subparsers = parser.add_subparsers(dest="command", required=True)

    run_parser = subparsers.add_parser("run")
    run_parser.add_argument("inputs", nargs="+")
    run_parser.add_argument("--output", required=True)

    args = parser.parse_args(argv)

    try:
        if args.command == "run":
            run_dag(args.inputs, args.output)
            return 0
    except HarnessError as exc:
        print(f"mini_harness: {exc}", file=sys.stderr)
        return 1

    parser.error("unknown command")
    return 2


if __name__ == "__main__":
    raise SystemExit(main())
